INSERT INTO "tool_alias" ("folded", "tool_id")
SELECT a.folded, t.id
FROM jsonb_to_recordset('[{"folded":"claudeai","tool":"claude"},{"folded":"gpt","tool":"chatgpt"},{"folded":"bard","tool":"gemini"},{"folded":"microsoftcopilot","tool":"copilot"},{"folded":"bingchat","tool":"copilot"},{"folded":"mistral","tool":"lechat"},{"folded":"tongyiqianwen","tool":"qwen"},{"folded":"dall·e","tool":"dalle"},{"folded":"sdxl","tool":"stablediffusion"},{"folded":"flux1","tool":"flux"},{"folded":"leonardo","tool":"leonardoai"},{"folded":"firefly","tool":"adobefirefly"},{"folded":"runwayml","tool":"runway"},{"folded":"klingai","tool":"kling"},{"folded":"dreammachine","tool":"lumadreammachine"},{"folded":"resolve","tool":"davinciresolve"},{"folded":"adobephotoshop","tool":"photoshop"},{"folded":"kreaai","tool":"krea"},{"folded":"boltnew","tool":"bolt"},{"folded":"v0dev","tool":"v0"},{"folded":"aistudio","tool":"googleaistudio"},{"folded":"wp","tool":"wordpress"},{"folded":"googlesheet","tool":"googlesheets"},{"folded":"sheets","tool":"googlesheets"},{"folded":"openaicodex","tool":"codex"},{"folded":"vscode","tool":"visualstudiocode"},{"folded":"intellij","tool":"jetbrains"},{"folded":"pycharm","tool":"jetbrains"},{"folded":"js","tool":"javascript"},{"folded":"ts","tool":"typescript"},{"folded":"node","tool":"nodejs"},{"folded":"reactjs","tool":"react"},{"folded":"vuejs","tool":"vue"},{"folded":"sveltekit","tool":"svelte"},{"folded":"golang","tool":"go"},{"folded":"hf","tool":"huggingface"},{"folded":"jupyternotebook","tool":"jupyter"},{"folded":"colab","tool":"googlecolab"},{"folded":"postgres","tool":"postgresql"},{"folded":"mcp","tool":"modelcontextprotocol"},{"folded":"integromat","tool":"make"},{"folded":"ifthisthenthat","tool":"ifttt"},{"folded":"microsoftpowerautomate","tool":"powerautomate"},{"folded":"appleshortcuts","tool":"raccourcis"},{"folded":"shortcuts","tool":"raccourcis"},{"folded":"appsscript","tool":"googleappsscript"},{"folded":"amazonalexa","tool":"alexa"},{"folded":"homekit","tool":"applehome"},{"folded":"hue","tool":"philipshue"},{"folded":"smartlife","tool":"tuya"},{"folded":"rpi","tool":"raspberrypi"},{"folded":"pico","tool":"raspberrypipico"},{"folded":"fusion360","tool":"fusion"},{"folded":"prusaresearch","tool":"prusa"},{"folded":"nvidiajetson","tool":"jetsonnano"}]'::jsonb) AS a(folded text, tool text)
JOIN "tool" t ON t.folded = a.tool;
--> statement-breakpoint
-- La bascule, étape 1 : tous les libellés existants dans une table temporaire (elle disparaît avec
-- la connexion ; la migration l'efface aussi). Chaque libellé arrive avec son rang (WITH
-- ORDINALITY : la position dans le tableau, à partir de 1), son nom replié et son adresse, calculés
-- par les deux fonctions ci-dessus : aucun libellé n'est collé dans le SQL, tout passe par des
-- colonnes. « listed » : le projet est public, non retiré, d'un auteur dont l'adresse est vérifiée
-- (il peut donner son nom à un « Autre », relecture juridique jur-T14).
CREATE TEMP TABLE r6b_label AS
SELECT 'project'::text AS kind, p.id::text AS owner, l.label, l.n::int AS pos, p.created_at AS at,
  (p.visibility = 'public' AND p.removed_at IS NULL
    AND EXISTS (SELECT 1 FROM "user" u WHERE u.id = p.author_id AND u.email_verified)) AS listed,
  pg_temp.r6b_fold(l.label) AS folded, pg_temp.r6b_slug(l.label) AS slug, CAST(NULL AS uuid) AS tool_id
FROM "project" p CROSS JOIN LATERAL unnest(p.tools) WITH ORDINALITY AS l(label, n)
WHERE btrim(l.label) <> ''
UNION ALL
SELECT 'profile', pr.user_id, l.label, l.n::int, pr.updated_at, false,
  pg_temp.r6b_fold(l.label), pg_temp.r6b_slug(l.label), CAST(NULL AS uuid)
FROM "profile" pr CROSS JOIN LATERAL unnest(pr.favorite_tools) WITH ORDINALITY AS l(label, n)
WHERE btrim(l.label) <> '';
--> statement-breakpoint
-- Étape 2 : chaque libellé rejoint l'outil du catalogue qui porte son nom replié, sinon celui dont
-- c'est un alias (les deux clés sont uniques : une seule ligne possible, et un index lu).
UPDATE r6b_label l SET tool_id = COALESCE(
  (SELECT t.id FROM "tool" t WHERE t.folded = l.folded),
  (SELECT a.tool_id FROM "tool_alias" a WHERE a.folded = l.folded));
--> statement-breakpoint
-- Étape 3 : les libellés restants deviennent des « Autre », un seul par nom replié. DISTINCT ON garde,
-- pour chaque nom, le libellé du plus ancien projet LISTÉ (un projet privé ne donne pas son nom,
-- jur-T14), sinon du plus ancien ; l'outil prend la date de ce projet, pour compter « en attente
-- depuis plus d'une semaine ». Sans famille, sans auteur (created_by reste nul, sec-A5).
--
-- L'adresse : la première libre parmi « claude », « claude-2 », « claude-3 »… Un bloc DO est un petit
-- programme PL/pgSQL que PostgreSQL exécute une fois : il crée les « Autre » UN PAR UN, si bien que
-- l'adresse prise par l'un compte pour le suivant. Compter les adresses déjà prises (l'ancienne
-- version) ne suffisait pas (relecture de sécurité sec-B3) : « Claude 2 » a l'adresse claude-2, et
-- « Claude ✨ » (adresse claude, prise par le catalogue) recevait aussi claude-2 : 23505, migration
-- arrêtée. Ici chaque suffixe est essayé jusqu'à ce qu'aucun outil ne le porte (NOT EXISTS, lu sur
-- l'index unique de tool.slug) ; la boucle s'arrête toujours, les outils étant en nombre fini. Les
-- noms passent par l'ordre de leur nom replié : le premier garde l'adresse sans suffixe.
DO $r6b$
DECLARE
  o record;
  candidate text;
  n int;
BEGIN
  FOR o IN
    SELECT DISTINCT ON (l.folded) l.folded, l.label AS name, l.slug, l.at
    FROM r6b_label l WHERE l.tool_id IS NULL
    ORDER BY l.folded, l.listed DESC, l.at, l.kind, l.owner, l.pos
  LOOP
    n := 1;
    candidate := o.slug;
    LOOP
      EXIT WHEN NOT EXISTS (SELECT 1 FROM "tool" t WHERE t.slug = candidate);
      n := n + 1;
      candidate := o.slug || '-' || n;
    END LOOP;
    INSERT INTO "tool" ("id", "slug", "name", "folded", "status", "family", "description_fr", "description_en", "site_url", "created_at", "created_by", "admitted_at")
    VALUES (gen_random_uuid(), candidate, o.name, o.folded, 'other', NULL, NULL, NULL, NULL, o.at, NULL, NULL);
  END LOOP;
END
$r6b$;
--> statement-breakpoint
-- Étape 4 : les libellés des « Autre » qu'on vient de créer prennent leur outil.
UPDATE r6b_label l SET tool_id = t.id FROM "tool" t WHERE l.tool_id IS NULL AND t.folded = l.folded;
--> statement-breakpoint
-- Étape 5 : les outils de chaque projet, dans l'ordre d'origine, sans doublon (« Chat GPT » et
-- « ChatGPT » dans le même projet ne font qu'un outil : on garde le premier). « label » garde le nom
-- tel que l'auteur l'a tapé pour un « Autre » (sec-B8) ; null pour un outil du catalogue.
INSERT INTO "project_tool" ("project_id", "tool_id", "position", "label")
SELECT d.owner::uuid, d.tool_id, (row_number() OVER (PARTITION BY d.owner ORDER BY d.pos) - 1)::smallint,
  CASE WHEN t.status = 'catalogue' THEN NULL ELSE d.label END
FROM (
  SELECT DISTINCT ON (owner, tool_id) owner, tool_id, pos, label
  FROM r6b_label WHERE kind = 'project' ORDER BY owner, tool_id, pos
) d JOIN "tool" t ON t.id = d.tool_id;
--> statement-breakpoint
-- Étape 6 : de même pour les outils favoris des profils.
INSERT INTO "profile_tool" ("user_id", "tool_id", "position", "label")
SELECT d.owner, d.tool_id, (row_number() OVER (PARTITION BY d.owner ORDER BY d.pos) - 1)::smallint,
  CASE WHEN t.status = 'catalogue' THEN NULL ELSE d.label END
FROM (
  SELECT DISTINCT ON (owner, tool_id) owner, tool_id, pos, label
  FROM r6b_label WHERE kind = 'profile' ORDER BY owner, tool_id, pos
) d JOIN "tool" t ON t.id = d.tool_id;
--> statement-breakpoint
-- Étape 7 : les vieilles adresses (« chat-gpt ») d'un libellé rattaché à un outil du catalogue
-- mènent à sa page. Jamais une redirection égale à l'adresse d'un outil (sec-A2).
INSERT INTO "tool_slug_redirect" ("slug", "tool_id")
SELECT DISTINCT ON (l.slug) l.slug, l.tool_id
FROM r6b_label l JOIN "tool" t ON t.id = l.tool_id
WHERE t.status = 'catalogue' AND l.slug <> t.slug
  AND NOT EXISTS (SELECT 1 FROM "tool" x WHERE x.slug = l.slug)
ORDER BY l.slug, l.at;
--> statement-breakpoint
